// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public {
        c = new ERCDDAToken(1000, "Token", "TKN");
    }
    function testFuzz_property(uint256 burnAmount) public {
        uint256 ownerBalance = c.balanceOf(address(this));
        burnAmount = bound(burnAmount, 1, ownerBalance);
        uint256 totalSupplyBefore = c.totalSupply();
        c.burn(burnAmount);
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyAfter <= totalSupplyBefore);
    }
}
